"""Bonus port burst configuration a test scenario asks for, and its constants.

A burst is generated by turning the ASIC bonus ports into extra FWS flood generators, capped by an ingress
ACL policer. BurstConfig is what a test scenario declares; BurstConfigConsts holds its defaults and the SDK
field names the configuration is serialized into.
"""
from dataclasses import dataclass
from typing import Dict, List

from ngts.constants.performance_constants import PerfConsts


class BurstConfigConsts:
    # Bonus Port Burst
    # A burst is generated by turning the ASIC bonus ports into extra FWS flood generators, capped by an
    # ingress ACL policer. See the BurstConfig dataclass below for what a test scenario can configure.
    BURST_CONFIG_FILE_NAME = "burst_config.json"
    BURST_DEFAULT_CIR = 1
    BURST_DEFAULT_CBS = 10
    BURST_DEFAULT_EBS = 10
    BURST_DEFAULT_NUM_PACKETS = 8
    # The burst runs as a traffic pattern of its own, named after the scenario it bursts on top of.
    BURST_SCENARIO_SUFFIX = "burst"
    # Field names of the SDK BurstConfig dataclass, which the burst configuration file is deserialized into.
    BURST_FIELD_CIR = "committed_information_rate"
    BURST_FIELD_CBS = "committed_burst_size"
    BURST_FIELD_EBS = "excess_burst_size"
    BURST_FIELD_PACKET_SIZE = "packet_size"
    BURST_FIELD_NUM_PACKETS = "num_packets"
    BURST_FIELD_PORTS = "ports"


@dataclass
class BurstConfig:
    """
    Bonus port burst a test scenario asks for.

    The ASIC bonus ports are turned into extra full wire speed generators and an ingress ACL policer caps
    how much they may inject, so cir/cbs/ebs shape the burst in hardware while packet_size/num_packets shape
    the traffic stream seeding it and dscp picks the traffic class it rides.

    The field names are the short ones a scenario declares, e.g. BurstConfig(cir=1, cbs=10, ebs=1). The SDK
    names them in full in its own BurstConfig dataclass, and to_sdk_json translates between the two.
    """
    cir: int = BurstConfigConsts.BURST_DEFAULT_CIR
    cbs: int = BurstConfigConsts.BURST_DEFAULT_CBS
    ebs: int = BurstConfigConsts.BURST_DEFAULT_EBS
    packet_size: int = PerfConsts.PACKET_SIZE_256
    num_packets: int = BurstConfigConsts.BURST_DEFAULT_NUM_PACKETS
    # Picks which traffic class the burst rides on the wire. DVS_LOSSY_TC/DVS_LOSSLESS_TC are DSCP values (not
    # raw TC numbers) that dscp_to_tc() maps to a priority-group/TC pair, same as the regular lossy/lossless
    # streams. The default (lossy) makes the burst share the DUT's lossy queue/PG rather than the lossless one.
    # The test also reads this value (has_lossy/has_lossless) to decide whether ECN marking is expected on
    # tx_ecn_marked_tc_4, so switching to DVS_LOSSLESS_TC changes what the test expects there too.
    dscp: int = PerfConsts.DVS_LOSSY_TC

    def to_sdk_json(self, ports: List[str]) -> Dict:
        """
        Serialize to the fields of the SDK BurstConfig dataclass, which the SDK reads the burst from.

        The SDK builds it with BurstConfig(**json.load(f)), so the result must hold exactly the fields that
        dataclass declares: an unexpected one raises TypeError there. dscp is therefore left out, it shapes
        only the traffic stream and means nothing to the policer.

        Args:
            ports: Ports the bonus ports flood the burst to, as SDK ports in hex format.

        Returns:
            dict: The burst configuration as the SDK expects to deserialize it.
        """
        return {BurstConfigConsts.BURST_FIELD_CIR: self.cir,
                BurstConfigConsts.BURST_FIELD_CBS: self.cbs,
                BurstConfigConsts.BURST_FIELD_EBS: self.ebs,
                BurstConfigConsts.BURST_FIELD_PACKET_SIZE: self.packet_size,
                BurstConfigConsts.BURST_FIELD_NUM_PACKETS: self.num_packets,
                BurstConfigConsts.BURST_FIELD_PORTS: ports}
